<template>
  <span class="inline-block">{{ displayText }}<span class="animate-pulse text-accent-gold">|</span></span>
</template>

<script>
export default {
  name: 'TypeWriter',
  props: {
    text: { type: String, required: true },
    speed: { type: Number, default: 80 },
    delay: { type: Number, default: 0 },
  },
  data() {
    return {
      displayText: '',
      currentIndex: 0,
    }
  },
  mounted() {
    setTimeout(() => {
      this.type()
    }, this.delay)
  },
  methods: {
    type() {
      if (this.currentIndex < this.text.length) {
        this.displayText += this.text.charAt(this.currentIndex)
        this.currentIndex++
        setTimeout(this.type, this.speed)
      }
    },
  },
}
</script>
